INSERT INTO `chat_session` ( `user_id`, `source`, `platform`, `session_id`, `parent_conversation_id`, `title`, `message_count`, `start_time`, `end_time`, `session_json` ) VALUES
(#{item.userId}, #{item.source}, #{item.platform}, #{item.sessionId}, #{item.parentConversationId}, #{item.title}, #{item.messageCount}, #{item.startTime}, #{item.endTime}, #{item.sessionJson})
ON DUPLICATE KEY UPDATE `user_id` = VALUES(`user_id`), `source` = VALUES(`source`), `platform` = VALUES(`platform`), `parent_conversation_id` = VALUES(`parent_conversation_id`), `title` = VALUES(`title`), `message_count` = VALUES(`message_count`), `start_time` = VALUES(`start_time`), `end_time` = VALUES(`end_time`), `session_json` = VALUES(`session_json`);
